<span class="line"><span style="color:#C792EA;">  const</span><span style="color:#BABED8;"> app</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> NestFactory</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">createMicroservice</span><span style="color:#89DDFF;">&lt;</span><span style="color:#FFCB6B;">MicroserviceOptions</span><span style="color:#89DDFF;">&gt;</span><span style="color:#F07178;">(</span></span>
